R=Path(__file__).parent
OLIVE='#384938'; INK='#292D29'; MUTED='#626B60'; CREAM='#F5F2E9'; RED='#98382F'
def t(s,size=16,color=INK,weight='regular'):
 return {'Text':{'text':s,'modifiers':{'fontSize':size,'fontWeight':weight,'foregroundColor':color}}}
def v(es,**m):return {'VStack':{'spacing':14,'elements':es,'modifiers':{'hAlignment':'leading','maxWidthInfinity':True,**m}}}
def b(label,action,revision=1):
 return {'Button':{'keypath':'meeting.'+action,'label':label,'payload':{'sessionID':'synthetic-meeting-01','planRevision':revision,'operationID':'fixture-'+action},'modifiers':{'background':OLIVE,'foregroundColor':'#FFFFFF','padding':12,'cornerRadius':10,'fontWeight':'semibold'}}}
def card(title,body):return v([t(title,19,OLIVE,'semibold')]+body,background='#FFFFFF',padding=22,cornerRadius=16)
def rows(names,status):return [t(f'{n}  ·  {s}',16) for n,s in zip(names,status)]
