 sk=v([t('HAVEN  /  '+kicker,13,OLIVE,'semibold'),t(title,32,INK,'bold'),v([t(notice,18,RED if id in ['new-participant','offline','declined'] else OLIVE,'semibold')],background=CREAM,padding=18,cornerRadius=12),{'HStack':{'spacing':20,'elements':[card(left[0],left[1]),card(right[0],right[1])],'modifiers':{'vAlignment':'top','maxWidthInfinity':True,'layoutVariants':[{'maxAvailableWidth':700,'axis':'vertical'}]}}},v(actions),t('Privat møte · Plan '+str(revision)+' · Eksempeldata',12,MUTED)],padding=24,background=CREAM)
 if id=='recording':
  sk['VStack']['elements'].insert(3,sk['VStack']['elements'].pop(4))
 cfg={'name':'Møte · '+title,'description':'Designforslag. Syntetiske data. Ingen lyd eller levering.','uuid':str(uuid.uuid5(uuid.NAMESPACE_URL,'haven:meeting-design:'+id)),'cellReferences':{},'skeleton':sk}
 (R/'skeleton'/f'{id}.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2))
 states.append({'id':id,'title':title})
