add('ready','Alle har godkjent','PRIVAT MØTE','3 av 3 har aktivt godkjent plan 1. Mikrofonen er fortsatt av.',('Avtalt behandling',terms),('Deltakere',rows(['Ada · møteleder · deg','Bjørn','Celine'],['Godkjent plan 1','Godkjent plan 1','Godkjent plan 1'])),[b('Start opptak','recording.start'),b('Trekk tilbake min godkjenning','consent.revoke')])
